//! Nested catalogs: compliance, UI target, models.
//!
//! Each module holds a routing view only. The sources stay authoritative:
//! `oscal/` JSON for controls, the sealed `json_render` blob for components,
//! the live `chat_router` catalog for providers/models.

pub mod compliance;
pub mod models;
pub mod ui;

//! Compliance catalog: control tags → OSCAL controls → candidate operations.
//!
//! Table is `oscal/TAG-TAXONOMY.md` as code; `oscal/catalogs/etched-catalog`
//! is authoritative. Qualifier tags (`action:*`, `approval:*`, `surface:*`,
//! `data:*`, `model:*`) never match controls — they steer the decision.

use crate::model::Operation;

/// One taxonomy row: tag, control, candidate `plugin/method` operations.
/// A `*` method means any method of the plugin.
const TAXONOMY: &[(&str, &str, &[&str])] = &[
    ("pii", "etched-pt-1", &["schema_tag_registry/tag-registry.get-policy"]),
    (
        "access-control",
        "etched-ac-1",
        &["elevation/authorize_task", "schema_tag_registry/*"],
    ),
    ("audit", "etched-au-1", &["identity_sled/*", "routing_decision/*"]),
    ("retention", "etched-si-1", &["cron/schedule", "workflows/*"]),
    ("integrity", "etched-in-1", &["identity_sled/*", "web3/*"]),
];

/// A control the request matched, with its candidate operations.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ControlMatch {
    pub control: String,
    pub operations: Vec<Operation>,
}

fn is_control_tag(tag: &str) -> bool {
    !tag.contains(':')
}

fn split_operation(spec: &str) -> Operation {
    match spec.split_once('/') {
        Some((plugin, method)) => Operation {
            plugin: plugin.to_string(),
            method: method.to_string(),
        },
        None => Operation {
            plugin: spec.to_string(),
            method: "*".to_string(),
        },
    }
}

/// Resolve request tags to controls, keeping taxonomy order and dropping
/// controls outside the profile. Unknown control tags match nothing —
/// a tag miss is a refusal downstream, never a default-allow.
pub fn match_controls(tags: &[String], profile_controls: &[String]) -> Vec<ControlMatch> {
    let mut out = Vec::new();
    for (tag, control, ops) in TAXONOMY {
        if !tags.iter().any(|t| t == tag) {
            continue;
        }
        if !profile_controls.iter().any(|c| c == control) {
            continue;
        }
        if out.iter().any(|m: &ControlMatch| m.control == *control) {
            continue;
        }
        out.push(ControlMatch {
            control: control.to_string(),
            operations: ops.iter().map(|s| split_operation(s)).collect(),
        });
    }
    out
}

/// True when the request carries the two-person-rule marker.
pub fn is_root(tags: &[String]) -> bool {
    tags.iter().any(|t| t == "approval:root")
}

#[cfg(test)]
mod tests {
    use super::*;

    fn profile() -> Vec<String> {
        vec![
            "etched-pt-1".into(),
            "etched-ac-1".into(),
            "etched-au-1".into(),
            "etched-si-1".into(),
            "etched-in-1".into(),
        ]
    }

    #[test]
    fn each_taxonomy_tag_resolves() {
        let cases = [
            ("pii", "etched-pt-1", 1),
            ("audit", "etched-au-1", 2),
            ("access-control", "etched-ac-1", 2),
            ("retention", "etched-si-1", 2),
            ("integrity", "etched-in-1", 2),
        ];
        for (tag, control, op_count) in cases {
            let m = match_controls(&[tag.into()], &profile());
            assert_eq!(m.len(), 1, "tag {tag}");
            assert_eq!(m[0].control, control);
            assert_eq!(m[0].operations.len(), op_count, "tag {tag}");
        }
    }

    #[test]
    fn qualifiers_never_match_and_miss_is_empty() {
        let tags: Vec<String> = vec![
            "action:publish".into(),
            "surface:web".into(),
            "bogus".into(),
        ];
        assert!(match_controls(&tags, &profile()).is_empty());
    }

    #[test]
    fn profile_filters_controls() {
        let m = match_controls(&["pii".into(), "audit".into()], &["etched-au-1".into()]);
        assert_eq!(m.len(), 1);
        assert_eq!(m[0].control, "etched-au-1");
    }

    #[test]
    fn duplicate_tags_match_once() {
        let m = match_controls(&["audit".into(), "audit".into()], &profile());
        assert_eq!(m.len(), 1);
    }

    #[test]
    fn root_marker_detected() {
        assert!(is_root(&["approval:root".into()]));
        assert!(!is_root(&["action:write".into()]));
    }
}

//! UI catalog: component support per renderer target.
//!
//! Mapping is `docs/DROP-IN-SPEC.md` §2.1–§2.3 as code; the sealed
//! `json_render` blob is authoritative. A target renders what it supports
//! and degrades the rest predictably — never drops an action or a refusal.

use crate::model::Surface;

/// How a component renders on a target.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Support {
    /// Renders natively.
    Full,
    /// Renders with a predictable fallback (attachment, modal, context line).
    Fallback(FallbackKind),
    /// Target cannot render it; the reply must say so, not drop it.
    Unsupported,
}

/// Predictable degradations from the §2.1 mapping.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum FallbackKind {
    /// Large tables: attached file plus summary lines.
    AttachmentPlusSummary,
    /// Selects and inputs: modal with the control.
    Modal,
    /// Status, receipts, decisions: context line.
    ContextLine,
}

/// Targets without an implemented mapping yet (`docs/DROP-IN-SPEC.md` §2.1:
/// Teams and email are "later"). Any check against them degrades explicitly.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum TargetStatus {
    Implemented,
    Planned,
}

pub fn target_status(target: Surface) -> TargetStatus {
    match target {
        Surface::Web | Surface::TeamChat => TargetStatus::Implemented,
        Surface::Teams | Surface::Email => TargetStatus::Planned,
    }
}

/// Component support on team chat. Web supports every catalog component;
/// unknown components are unsupported everywhere (they fail validation
/// before rendering, so reaching here is a caller bug — still explicit).
pub fn check(target: Surface, component: &str, rows: Option<usize>) -> Support {
    match target {
        Surface::Web => Support::Full,
        Surface::TeamChat => match component {
            "heading" | "text" | "button" | "action" | "key_value" | "list"
            | "status" | "progress" | "receipt" | "refusal" | "approval_request"
            | "redaction_notice" | "policy_decision" => Support::Full,
            "table" => match rows {
                Some(n) if n > 20 => {
                    Support::Fallback(FallbackKind::AttachmentPlusSummary)
                }
                _ => Support::Full,
            },
            "select" | "input" => Support::Fallback(FallbackKind::Modal),
            _ => Support::Unsupported,
        },
        Surface::Teams | Surface::Email => match component {
            "receipt" | "refusal" | "approval_request" | "redaction_notice" => {
                Support::Unsupported
            }
            _ => Support::Unsupported,
        },
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn web_supports_everything() {
        assert_eq!(check(Surface::Web, "anything_new", None), Support::Full);
    }

    #[test]
    fn team_chat_governance_components_are_native() {
        for c in ["receipt", "refusal", "approval_request", "redaction_notice"] {
            assert_eq!(check(Surface::TeamChat, c, None), Support::Full, "{c}");
        }
    }

    #[test]
    fn team_chat_large_table_degrades_to_attachment() {
        assert_eq!(
            check(Surface::TeamChat, "table", Some(500)),
            Support::Fallback(FallbackKind::AttachmentPlusSummary)
        );
        assert_eq!(
            check(Surface::TeamChat, "table", Some(5)),
            Support::Full
        );
    }

    #[test]
    fn team_chat_inputs_degrade_to_modal() {
        assert_eq!(
            check(Surface::TeamChat, "select", None),
            Support::Fallback(FallbackKind::Modal)
        );
    }

    #[test]
    fn planned_targets_are_explicit() {
        assert_eq!(target_status(Surface::Teams), TargetStatus::Planned);
        assert_eq!(
            check(Surface::Teams, "text", None),
            Support::Unsupported
        );
    }
}

//! Model catalog: provider/model selection over a caller-supplied registry.
//!
//! The live `chat_router` catalog is authoritative. This module only matches:
//! `model:*` request tags must all be covered by the entry's capabilities,
//! and the first covering entry wins (registries are preference-ordered).
//! No provider or model names live here — fixtures in tests are marked.

/// One registry entry, supplied by the caller (runtime: `chat_router`).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ModelEntry {
    pub id: String,
    pub provider: String,
    pub capabilities: Vec<String>,
}

/// First registry entry covering every `model:*` tag's requirement.
/// No requirements → first entry. No covering entry → `None` (refuse
/// upstream, never fall back to an unqualified model silently).
pub fn select<'a>(tags: &[String], registry: &'a [ModelEntry]) -> Option<&'a ModelEntry> {
    let required: Vec<&str> = tags
        .iter()
        .filter_map(|t| t.strip_prefix("model:"))
        .collect();
    registry.iter().find(|entry| {
        required
            .iter()
            .all(|r| entry.capabilities.iter().any(|c| c == r))
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Test fixtures only — not real providers.
    fn registry() -> Vec<ModelEntry> {
        vec![
            ModelEntry {
                id: "fixture-chat".into(),
                provider: "fixture".into(),
                capabilities: vec!["chat".into()],
            },
            ModelEntry {
                id: "fixture-vision".into(),
                provider: "fixture".into(),
                capabilities: vec!["chat".into(), "vision".into()],
            },
        ]
    }

    #[test]
    fn no_requirements_selects_first() {
        let reg = registry();
        assert_eq!(select(&["audit".into()], &reg).unwrap().id, "fixture-chat");
    }

    #[test]
    fn requirement_selects_covering_entry() {
        let reg = registry();
        let got = select(&["model:vision".into()], &reg).unwrap();
        assert_eq!(got.id, "fixture-vision");
    }

    #[test]
