//! Governed e2e driver (throwaway): decide an identity_sled read for the
//! control-plane chatbot, then print the exact mount call it must execute.
//!
//! Reads /tmp/e2e/grants.json (effective grants extracted from
//! /dev/shm/opdbus/capability-grants.json: principal's own 54, which already
//! cover its $ROOT group — no group-union inference needed).
//! Prints the Decision as JSON. Performs NO mount call: execution belongs to
//! the identity through its own mount.

use catalog_routing::{decide, ActionKind, Grants, Profile, Request, Surface, Verdict};
use std::collections::BTreeSet;

fn main() {
    let grants_file = std::fs::read_to_string("/tmp/e2e/grants.json").unwrap();
    let grants_json: serde_json::Value = serde_json::from_str(&grants_file).unwrap();
    let caps: BTreeSet<String> = grants_json["effective_grants"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap().to_string())
        .collect();
    let grants = Grants {
        capabilities: caps.into_iter().collect(),
    };
    let request = Request {
        actor: "1262e982-14c1-44d4-0771-7ce74213211b".to_string(),
        surface: Surface::Web,
        action: ActionKind::Read,
        tags: vec!["audit".to_string(), "action:read".to_string()],
        payload_ref: "get_own_identity:{}".to_string(),
    };
    let profile = Profile {
        id: "small-business-portal".to_string(),
        controls: vec![
            "etched-pt-1".to_string(),
            "etched-ac-1".to_string(),
            "etched-au-1".to_string(),
            "etched-si-1".to_string(),
            "etched-in-1".to_string(),
        ],
    };
    let decision = decide(&request, &profile, &grants);
    println!("{}", serde_json::to_string_pretty(&decision).unwrap());
    match &decision.verdict {
        Verdict::Allow => {
            let op = decision
                .operations
                .iter()
                .find(|o| o.plugin == "identity_sled" && o.method == "get_own_identity")
                .expect("audit must offer get_own_identity");
            println!(
                "CALL: printf '%s' '{{}}' > /run/mount/3tchedfs/operations/{}/{}/call",
                op.plugin, op.method
            );
            println!(
                "CAP: {} (sealed identity_sled v4.7.0, blob bb45d8f4)",
                op.capability.as_deref().unwrap_or("<unsealed>")
            );
        }
        other => println!("NO CALL: {other:?}"),
    }
}

