//! Trim replay (throwaway): decide() under the proposed trimmed chatbot set.
//! Run: cargo run --example trim_replay
//! Expected: audit Allow[get_own_identity], pii Refuse(schema-registry read),
//! retention Allow[start_workflow], integrity Refuse(method-not-sealed),
//! root NeedsApproval, bogus Refuse(no-control-match).

use catalog_routing::{
    decide, ActionKind, Grants, Profile, Request, Surface, Verdict,
};

fn trimmed() -> Grants {
    // 25 obs + answer path (exact strings from the live file, minus removed).
    Grants {
        capabilities: vec![
            "cap.data.cozo.system-graph.read@v1",
            "cap.identity.sled.self.read@v1",
            "cap.software.3tched-router.chat@v1",
            "cap.software.3tched-router.config.read@v1",
            "cap.software.3tched-router.models.read@v1",
            "cap.software.3tched-router.providers.read@v1",
            "cap.software.3tched-router.route.resolve@v1",
            "cap.software.3tched-router.router.read@v1",
            "cap.software.3tched-router.routes.read@v1",
            "cap.software.3tched-router.state.read@v1",
            "cap.software.3tched-router.structured-output.read@v1",
            "cap.software.3tched-router.tools.read@v1",
            "cap.software.3tched-router.ui-surfaces.read@v1",
            "cap.software.chat-router.generation.read@v1",
            "cap.software.tched-router.agent.route.self.read@v1",
            "cap.software.tched-router.model.binding.read@v1",
            "cap.software.tched-router.router.read@v1",
            "chat.context",
            "chat_response.respond",
            "cognitive.read",
            "cognitive.sequential_thinking",
            "cognitive.typescript_pro",
            "freedesktop.read",
            "model_registry.read",
            "notebooklm.read",
            "openflow.read",
            "snowball.read",
            "workflows.read",
        ]
        .into_iter()
        .map(str::to_string)
        .collect(),
    }
}

fn profile() -> Profile {
    Profile {
        id: "small-business-portal".into(),
        controls: ["etched-pt-1", "etched-ac-1", "etched-au-1", "etched-si-1", "etched-in-1"]
            .iter()
            .map(|s| s.to_string())
            .collect(),
    }
}

fn req(tags: &[&str]) -> Request {
    Request {
        actor: "control-plane-chatbot".into(),
        surface: Surface::Web,
        action: ActionKind::Read,
        tags: tags.iter().map(|s| s.to_string()).collect(),
        payload_ref: "trim-replay".into(),
    }
}

fn main() {
    let g = trimmed();
    let p = profile();
    let audit = decide(&req(&["audit", "action:read"]), &p, &g);
    assert_eq!(audit.verdict, Verdict::Allow);
    assert!(audit.operations.iter().any(|o| o.method == "get_own_identity"));
    println!("audit -> Allow {:?}", audit.operations.iter().map(|o| &o.method).collect::<Vec<_>>());

    let pii = decide(&req(&["pii", "action:publish"]), &p, &g);
    assert_eq!(
        pii.verdict,
        Verdict::Refuse {
            missing_capability: Some("cap.governance.schema-tag-registry.read@v1".into()),
            rule: "etched-pt-1".into(),
        }
    );
    println!("pii -> Refuse (add the +1 read to resolve)");

    let ret = decide(&req(&["retention", "action:write"]), &p, &g);
    assert_eq!(ret.verdict, Verdict::Allow);
    assert_eq!(ret.operations.len(), 1);
    assert_eq!(ret.operations[0].method, "start_workflow");
    println!("retention -> Allow [start_workflow]");

    let integ = decide(&req(&["integrity"]), &p, &g);
    assert_eq!(
        integ.verdict,
        Verdict::Refuse {
            missing_capability: None,
            rule: "method-not-sealed:web3.anchor".into(),
        }
    );
    println!("integrity -> Refuse method-not-sealed");

    let root = decide(&req(&["integrity", "approval:root"]), &p, &g);
    assert!(matches!(root.verdict, Verdict::NeedsApproval { need: 2, .. }));
    println!("root -> NeedsApproval 0-of-2");

    let bogus = decide(&req(&["bogus"]), &p, &g);
    assert!(matches!(bogus.verdict, Verdict::Refuse { .. }));
    println!("bogus -> Refuse no-control-match");
    println!("TRIM REPLAY OK");
}

