                    position: p.id.clone(),
                    role: role.clone(),
                });
            }
        }
        // Walk the reporting chain: missing parents are roots; cycles and
        // over-depth chains refuse.
        let mut chain = BTreeSet::new();
        chain.insert(p.id.as_str());
        let mut current = p.reports_to.as_deref();
        let mut depth = 1;
