    #[test]
    fn missing_attributes_skip_with_reason() {
        let chart = OrgChart {
            id: "gate".into(),
            positions: vec![Position {
                id: "p".into(),
                reports_to: None,
                roles: vec!["r".into()],
                members: vec![member("k", &[])],
