        let out = compile(&chart).unwrap();
        assert!(out.grants.is_empty());
        assert_eq!(out.skips.len(), 1);
        assert!(out.skips[0].reason.contains("compartment-a"));
    }

    #[test]
    fn duplicate_position_refuses() {
        let mk = || Position {
            id: "p".into(),
            reports_to: None,
            roles: vec![],
            members: vec![],
        };
        let chart = OrgChart {
            id: "dup".into(),
            positions: vec![mk(), mk()],
            roles: vec![],
        };
        assert!(matches!(
            compile(&chart),
            Err(ChartError::DuplicatePosition { .. })
        ));
    }
}

