                                    .iter()
                                    .map(|s| s.as_str())
                                    .collect::<Vec<_>>()
                                    .join(",")
                            ),
                        });
                    }
                }
            }
        }
    }
    for ((member_key, capability), (via_role, via_position)) in granted {
        out.grants.push(Grant {
            member_key,
            capability,
            via_role,
            via_position,
        });
