//! Live strict loop (throwaway): catalog hash -> pinned compile ->
//! verify -> decide -> print call. Execution happens in the identity
//! container afterwards; this binary performs no mount writes.
//! Run: cargo run --example live_loop

use catalog_routing::{
    decide,
    org_bridge::grants_for_verified,
    ActionKind, Profile, Request, Surface, Verdict,
};
use org_chart::{Member, OrgChart, Position, Role};
use sha2::{Digest, Sha256};
use std::fs;
use std::path::Path;

fn catalog_hash(dir: &Path) -> String {
    let mut entries: Vec<String> = fs::read_dir(dir)
        .unwrap()
        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
        .filter(|n| n.ends_with(".blob"))
        .collect();
    entries.sort();
    let mut h = Sha256::new();
    for name in &entries {
        let bytes = fs::read(dir.join(name)).unwrap();
        let file_hash = format!("{:x}", Sha256::digest(&bytes));
        h.update(format!("{name}:{file_hash}\n"));
    }
    format!("{:x}", h.finalize())
}

fn main() {
    let shm = Path::new("/dev/shm/opdbus/plugin-blobs");
    let h1 = catalog_hash(shm);
    println!("catalog hash @compile: {h1}");

    let grants_file = fs::read_to_string("/tmp/e2e/grants.json").unwrap();
    let grants_json: serde_json::Value = serde_json::from_str(&grants_file).unwrap();
    let principal = grants_json["principal"].as_str().unwrap().to_string();
    let keep: Vec<String> = vec![
        "cap.data.cozo.system-graph.read@v1",
        "cap.identity.sled.self.read@v1",
        "cap.software.3tched-router.chat@v1",
        "cap.software.3tched-router.config.read@v1",
        "cap.software.3tched-router.models.read@v1",
        "cap.software.3tched-router.providers.read@v1",
        "cap.software.3tched-router.route.resolve@v1",
        "cap.software.3tched-router.router.read@v1",
        "cap.software.3tched-router.routes.read@v1",
        "cap.software.3tched-router.state.read@v1",
        "cap.software.3tched-router.structured-output.read@v1",
        "cap.software.3tched-router.tools.read@v1",
        "cap.software.3tched-router.ui-surfaces.read@v1",
        "cap.software.chat-router.generation.read@v1",
        "cap.software.tched-router.agent.route.self.read@v1",
        "cap.software.tched-router.model.binding.read@v1",
        "cap.software.tched-router.router.read@v1",
        "chat.context",
        "chat_response.respond",
        "cognitive.read",
        "cron.read",
        "elevation.read",
        "freedesktop.read",
        "model_registry.read",
        "notebooklm.read",
        "openflow.read",
        "snowball.read",
        "workflows.read",
    ]
    .into_iter()
    .map(str::to_string)
    .collect();
    assert_eq!(keep.len(), 28, "trimmed keep-set is 28");

    let chart = OrgChart {
        id: "chatbot-desk".into(),
        roles: vec![Role {
            id: "reader".into(),
            capabilities: keep,
            requires_attributes: vec![],
        }],
        positions: vec![Position {
            id: "desk".into(),
            reports_to: None,
            roles: vec!["reader".into()],
            members: vec![Member {
                key: principal.clone(),
                attributes: vec![],
            }],
        }],
    };
    let output = org_chart::compile_pinned(&chart, Some(&h1)).unwrap();
    println!(
        "compiled: {} grants, {} skips, pinned={}",
        output.grants.len(),
        output.skips.len(),
        output.sealed_catalog_hash.as_deref().unwrap()
    );

    let h2 = catalog_hash(shm);
    println!("catalog hash @verify:  {h2}");
    let grants = grants_for_verified(&output, &principal, &h2).expect("seal verifies");
    println!("seal verified, {} effective grants", grants.capabilities.len());

    let request = Request {
        actor: principal,
        surface: Surface::Web,
        action: ActionKind::Read,
        tags: vec!["audit".into(), "action:read".into()],
        payload_ref: "live-loop:get_own_identity".into(),
    };
    let profile = Profile {
        id: "small-business-portal".into(),
        controls: ["etched-au-1".into()].into(),
    };
    let decision = decide(&request, &profile, &grants);
    assert_eq!(decision.verdict, Verdict::Allow);
    let op = decision
        .operations
        .iter()
        .find(|o| o.method == "get_own_identity")
        .expect("audit offers get_own_identity");
    println!(
        "DECIDE Allow cap={} blob-sealed",
        op.capability.as_deref().unwrap()
    );
    println!(
        "CALL: printf '%s' '{{}}' > /run/mount/3tchedfs/operations/{}/{}/call",
        op.plugin, op.method
    );
    println!("LIVE LOOP OK");
}

