65:export const dashboardReferences = manifest.menu_items.map(item => {
66:  const parts = item.placeholder ? [status("Coming Soon in the source", "This menu item had no page implementation to extract.", "warning")] : examples[item.id];
67:  if (!parts) throw new Error(`Missing reference composition: ${item.id}`);
68:  const elements: Spec["elements"] = {
69:    root: { type: "container", props: { className: null }, children: ["header", "reference", ...parts.map((_, i) => `section-${i}`)] },
70:    header: { type: "pageHeader", props: { title: item.label, subtitle: `${item.section} · static UI reference` } },
71:    reference: status("Static reference", "Illustrative data only. Layout adapted from operation-dashboard-ui-07; no live state or operational actions."),
72:  };
73:  parts.forEach((part, i) => { elements[`section-${i}`] = part; });
74:  return { ...item, spec: validateCanvasSpec({ root: "root", elements }) };
75:});
