77:export function findDashboardReference(query: string) {
78:  const words = query.toLowerCase().replace(/[^a-z0-9-]+/g, " ").trim();
79:  return [...dashboardReferences].sort((a, b) => b.label.length - a.label.length).find(item =>
80:    (` ${words} `).includes(` ${item.id} `) || (` ${words} `).includes(` ${item.label.toLowerCase()} `),
81:  );
82:}

