import { render, cleanup } from "../../test/native";
import SpecRenderer from "../../svelte/SpecRenderer.svelte";
import { afterEach } from "vitest";
afterEach(cleanup);
import { describe, expect, it } from "vitest";
import { validateCanvasSpec } from "./canvas-contract";
import { referenceChatResponse } from "./reference-chat";
import { storyReferences } from "./story-examples";

describe("story walkthrough", () => {
  it("renders every chapter from catalog components only", () => {
    expect(storyReferences.map(item => item.id)).toEqual(["stack", "identity", "lungs", "accountability", "compliance"]);
    for (const item of storyReferences) {
      expect(() => validateCanvasSpec(item.spec), item.id).not.toThrow();
      const markup = render(SpecRenderer, { spec: item.spec }).container.innerHTML;
      expect(markup, item.id).toContain("Static reference");
      expect(markup, item.id).not.toContain("Unknown component");
    }
  });

  it("opens with the first chapter and lists the rest", () => {
    const opening = referenceChatResponse("/ui-reference story");
    expect(opening?.canvasSpec).toBe(storyReferences[0].spec);
    expect(opening?.message.content).toContain("/ui-reference story followed by a chapter ID");
    expect(opening?.message.content).toContain("compliance");
  });

  it("routes chapters inside the story namespace without shadowing dashboard references", () => {
    const lungs = storyReferences.find(item => item.id === "lungs");
    expect(referenceChatResponse("/ui-reference story lungs")?.canvasSpec).toBe(lungs?.spec);
    const storyTrial = storyReferences.find(item => item.id === "accountability");
    expect(referenceChatResponse("/ui-reference story accountability")?.canvasSpec).toBe(storyTrial?.spec);
    // The dashboard's own accountability reference is still reachable directly.
    expect(referenceChatResponse("/ui-reference accountability")?.canvasSpec).not.toBe(storyTrial?.spec);
    expect(referenceChatResponse("/ui-reference story nonsense")?.canvasSpec).toBeUndefined();
  });

  it("keeps live identifiers and internal addresses out of the walkthrough", () => {
    const serialized = JSON.stringify(storyReferences.map(item => item.spec));
    expect(serialized).not.toMatch(/\b10\.\d+\.\d+\.\d+\b/);

import { mountedPluginSourcesPrompt } from "../../chat/mounted-plugin-sources";
import type { ChatResponse } from "../../chat/chat-adapter";
import type { ChatMode, NotebookDetail } from "../../chat/chat-mode";
import type { CatalogEntry } from "../../chat/ui-gallery";
import { canvasCatalog } from "./canvas-contract";
import { dashboardReferences, findDashboardReference } from "./dashboard-examples";
import { STORY_INDEX_ID, storyIndexMessage, storyReferences } from "./story-examples";

let referenceSequence = 0;

/** `/ui-reference story [chapter]` opens the product walkthrough; it has its own namespace. */
function storyChatResponse(query: string): ChatResponse | undefined {
  const [head, ...rest] = query.toLowerCase().split(/\s+/).filter(Boolean);
  if (head !== STORY_INDEX_ID) return undefined;
  const chapterId = rest.join(" ");
  const chapter = chapterId ? storyReferences.find(item => item.id === chapterId) : storyReferences[0];
  if (!chapter) {
    return { message: { id: `story-index-${referenceSequence}`, role: "agent", content: storyIndexMessage() } };
  }
  return {
    message: {
      id: `story-${chapter.id}-${referenceSequence}`,
      role: "agent",
      content: chapterId ? `${chapter.label}.` : `${chapter.label}.\n\n${storyIndexMessage()}`,
    },
    canvasSpec: chapter.spec,
  };
}

/** An explicit local command exposes the same examples to offline and connected chat. */
export function referenceChatResponse(message: string): ChatResponse | undefined {
  if (!/^\/ui-reference(?:\s|$)/i.test(message.trim())) return undefined;
  referenceSequence += 1;
  const query = message.trim().replace(/^\/ui-reference\s*/i, "");
  const story = storyChatResponse(query);
  if (story) return story;
  const reference = dashboardReferences.find(item => item.id === query.toLowerCase()) ?? findDashboardReference(query);
  if (reference) return {
    message: { id: `reference-${reference.id}-${referenceSequence}`, role: "agent", content: `${reference.label}: static reference composed from reusable catalog elements. Values are examples; controls do not operate the host.` },
    canvasSpec: reference.spec,
  };
  return {
    message: { id: `reference-index-${referenceSequence}`, role: "agent", content: `Use /ui-reference story for the 3tched walkthrough, or /ui-reference followed by a menu ID:\n\n${dashboardReferences.map(item => `${item.id} — ${item.label}${item.placeholder ? " (source placeholder)" : ""}`).join("\n")}` },
  };
}

/** Every connected mode may present a validated Canvas; UI render designs candidates. */
export function catalogPresentationMessage(message: string, mode?: ChatMode, notebook?: NotebookDetail | null, catalog?: CatalogEntry[]): string {
  const reference = findDashboardReference(message);
  const designMode = mode === "ui_render";
  const notebookMode = mode === "notebook_lm";
  return [
    designMode
      ? "UI render mode is a gallery for proposing possible interfaces. Compose distinct candidate designs from this application's implemented json-render components and label them as proposals for later review. Return a brief explanation and exactly one fenced spec block containing JSONL patches that build {root,elements} with flat element IDs. Do not claim any proposal has been promoted into the main catalog."
      : notebookMode
        ? "NotebookLM mode must render the selected notebook on the canvas. The canvas is the single fenced spec block; it appears under the chat. Answer the user in text, then put JSONL patches for the notebook interface in that canvas block. The root is a container. Its children are notebookHeader and notebookSourceList, using only the notebook facts below. Copy those facts into static props. Do not invent sources, titles, or URLs. Do not describe the notebook only in prose. If the facts say the notebook is unavailable, say so in text and omit the canvas block."
        : "Answer the user's request normally. This chat can also present a useful visual through the application's implemented json-render catalog in any mode. When a table, diagram, status view, or other structured interface helps, optionally include exactly one fenced spec block containing JSONL patches that build {root,elements} with flat element IDs. A plain-text answer is fine when a visual would not help.",
    notebookMode ? `Selected notebook facts:\n${JSON.stringify(notebook ?? { unavailable: true })}` : "",
    mountedPluginSourcesPrompt(),
    canvasCatalog.prompt({ mode: "inline" }),
    "For this application's canvas, build only static props and children in the spec block. No state patches, actions, bindings, HTML, remote URLs, chat controls or new component types. Pages are compositions of reusable elements. Label fictional data as illustrative; never claim it is live telemetry. A form preview does not authorize an operation. The visual does not change the selected mode, permissions, or model route. Each JSONL patch stream in a fence is its own scratch catalog object. A chat keeps all of them until that chat closes, and then every one of those objects is removed.",
    `Available reference menu IDs: ${dashboardReferences.map(item => item.id).join(", ")}.`,
    !designMode && catalog?.length
      ? `Promoted catalog compositions (the active catalog; prefer adapting one when it fits):\n${catalog.map(entry => `${entry.name}${entry.description ? ` — ${entry.description}` : ""}:\n${JSON.stringify(entry.spec)}`).join("\n\n")}`
      : "",
    reference ? `Relevant static reference (${reference.id}):\n${JSON.stringify(reference.spec)}` : "Choose reusable panels, tables, metrics and controls only if they fit the request.",
    `User request:\n${message}`,
  ].filter((part) => part.length > 0).join("\n\n");
}

